mod db;
use crate::db::{connection, pool};

pub fn startup_message() -> String {
    format!("{}:{}", connection::mode(), pool::mode())
}

fn main() {
    println!("{}", startup_message());
}

#[cfg(test)]
mod tests {
    #[test]
    fn secure_startup_mode_enabled() {
        assert_eq!(super::startup_message(), "secure:secure");
    }
}
